@js:
MD = 'disc';
clearUI();
let args = getArgs(java,source);
if(args.viewMode !== "setting"){
	infoMap["state"] = args.state;
	infoMap["order"] = args.order;
	infoMap["domain"] = args.domain;
}
infoMap["keyWord"] = args.keyWord;
infoMap["offset"] = args.offset + "";
infoMap.save();
//发现模式
if(args.viewMode == "discover"){
	pushUI(newTitle("🗽" + getHostUrl(java,source), MD));
	//自定义发现
	if(args.discoverMode == "customize") {
		pushUI(newButton("🔆自设发现🔆",MD,"changeDiscoverMode(java,source,'discover')",2));
		pushUI(newButton("🧑‍💻关注作者🧑‍💻",MD,"changeDiscoverMode(java,source,'authorNovel')",2));
		pushUI(newButton("【⚙️自定义发现参数配置⚙️】",MD,"changeWorkMode(java,source,'setting')",1));
		for (var i in args.UDDiscoverArr) {
			let charLength = args.UDDiscoverArr[i].replace(/[\u0391-\uFFE5]/g, 'aa').length;
			if(charLength > 16){
				colsTemp = 1;
			} else if(charLength > 10){
				colsTemp = 2;
			} else if(charLength > 4){
				colsTemp = 3;
			} else{
				colsTemp = 4;
			}
			pushUI(newUrl(args.UDDiscoverArr[i], args.UDDiscover[args.UDDiscoverArr[i]],colsTemp));
		}
	}
	//关注作者
	else if(args.discoverMode == "authorNovel") {
		pushUI(newButton("👓️发现模式👓️",MD,"changeDiscoverMode(java,source,'discover')",2));
		pushUI(newButton("🔆关注作者🔆",MD,"",2));
		let hasAuthor = false;
		pushUI(newButton("【⚙️关注作者参数配置⚙️】",MD,"changeWorkMode(java,source,'setting')",1));
		//自定义关注作者
		if(args.authors.length > 0){
			let calcWidth = 0;
			let colsTemp = 1;
			//分组下作者
			for (var i in args.authors){
				let charLength = args.authors[i].replace(/[\u0391-\uFFE5]/g, 'aa').length;
				if(charLength > 16){
					colsTemp = 1;
				} else if(charLength > 10){
					colsTemp = 2;
				} else if(charLength > 4){
					colsTemp = 3;
				} else{
					colsTemp = 4;
				}
				pushUI(newUrl(args.authors[i], initDiscoverUrl_A(args.authors[i]),colsTemp));
			}
		}
	}
	//传统发现
	else if(args.discoverMode == "discover") {
		pushUI(newButton("🔆传统发现🔆",MD,"changeDiscoverMode(java,source,'customize')",2));
		pushUI(newButton("🧑‍💻关注作者🧑‍💻",MD,"changeDiscoverMode(java,source,'authorNovel')",2));
		if(args.keyWord.length > 0){
			pushUI(newUrl(`🔎搜索【${args.keyWord}】`,initDiscoverUrl_S(args.keyWord),1));
		}
		let cateTitle = `⚙️ ${args.state.split(" ")[1]}小说按${args.order.split(" ")[1]}：⚙️`;
		pushUI(newButton(cateTitle,MD,"changeWorkMode(java,source,'setting')",29));
		for(let i in optionsJson.cate){
			pushUI(newUrl(optionsJson.cate[i],initDiscoverUrl(java,source,optionsJson.cate[i],args.offset),2));
		}

	} else {
		args.discoverMode = "discover";
		saveArgs(source, args);
		java.refreshExplore();
	}
}
//设置模式
else if(args.viewMode  == "setting"){
	//传统发现设置
	if(args.discoverMode == "discover"){
		pushUI(newButton("🔆👓️🔆传统发现设置🔆👓️🔆",MD,"",1));
		pushUI(newButton("👓️状态：",MD,"",3));
		pushUI(newToggle("state", " ",MD,optionsJson.state,"java.refreshExplore()",22));
		pushUI(newButton("👓️排序：",MD,"",3));
		pushUI(newToggle("order", " ",MD,optionsJson.order,"java.refreshExplore()",22));
		pushUI(newButton("👓️开始页数：",MD,"",2));
		pushUI(newText("offset",MD,"",22));
		pushUI(newButton("🔎关键字",MD,"",3));
		pushUI(newText("keyWord",MD,"",22));
	}
	//自设发现设置
	else if(args.discoverMode == "customize"){
		pushUI(newButton("🔆👓️🔆自设发现设置🔆👓️🔆",MD,"",1));
		pushUI(newText("自定义标题",MD,"",1));
		pushUI(newSelect("UDType", "⚙️ 添加发现类型", MD, ["👓️发现","🔎搜索","🧑‍💻作者"], "java.refreshExplore()", 1));
		if(infoMap["UDType"] == "🔎搜索") {
			pushUI(newText("搜索关键字",MD,"",1));
			pushUI(newButton("➕️添加自定义搜索➕️",MD,"addUDDiscover(java, source, infoMap, 'search')",1));
		} else if(infoMap["UDType"] == "🧑‍💻作者") {
			pushUI(newText("关注作者",MD,"",1));
			pushUI(newButton("➕️添加关注作者➕️",MD,"addUDDiscover(java, source, infoMap, 'author')",1));
		} else {
			pushUI(newSelect("state", " ", MD, optionsJson.state, "", 2));
			pushUI(newSelect("order", " ", MD, optionsJson.order, "", 2));
			pushUI(newSelect("cate", " ", MD, optionsJson.cate, "", 1));
			pushUI(newText("起始页数",MD,"",2));
			pushUI(newButton("➕️添加发现➕️",MD,"addUDDiscover(java, source, infoMap, 'discover')",2));
		}
		if(args.UDDiscoverArr.length > 0){
			pushUI(newButton("↙️删除选中❌️",MD,"delUDDiscover(java, source, infoMap)",1));
			pushUI(newSelect("UDDiscovers", "🧑‍💻 作者", MD, args.UDDiscoverArr, "", 1));
		}


	}
	//关注作者设置
	else if(args.discoverMode == "authorNovel"){
		pushUI(newButton("🔆🧑‍💻🔆关注作者设置🔆🧑‍💻🔆",MD,"",1));
		pushUI(newText("添加作者",MD,"",1));
		pushUI(newButton("➕️添加作者↗️", MD, "addAuthor(java, source, infoMap)", 2));
		java.log(args.authors.length)
		if(args.authors.length > 0){
			pushUI(newButton("↙️删除选中❌️",MD,"delAuthor(java, source, infoMap)",2));
			pushUI(newSelect("authors", "🧑‍💻 作者", MD, args.authors, "", 1));
		}
		}

} else if (args.viewMode  == "hosts") {
	pushUI(newButton("🔆🛜🔆域名相关设置🔆🛜🔆", MD, "", 1));
	pushUI(newSelect("protocal", " ", MD, ["http", "https"], "", 3));
	pushUI(newText("URL",MD,"",22));
	pushUI(newButton("➕️添加域名↗️", MD, "addHost(java, source, infoMap)", 2));
	pushUI(newButton("↙️删除选中❌️",MD,"delHost(java, source, infoMap)",2));
	pushUI(newSelect("domain", "⚙️ 域名", MD, args.hostArr, "switchHost(java, source, infoMap)", 1));
	pushUI(newButton("📥️获取域名📥️", MD, "getHostUrls(java, source)", 2));
	pushUI(newButton("📶连接测试⏱️", MD, "testConnet(java, source, infoMap)", 2));
}
//默认显示传统发现设置
else {
	args.viewMode = "discover";
	saveArgs(source, args);
	java.refreshExplore();
}
//设置模式显示确认取消
if(args.viewMode  != "discover"){
	pushUI(newButton("↪️　返　回　↩️",MD,"conmmitSetting(java,source,infoMap)",1));
} else {
	pushUI(newButton("⚙️域名配置⚙️",MD,"changeWorkMode(java,source,'hosts')",1));
}
let strUI = JSON.stringify(UI,null,"\t");
L(java,4,"\n发现界面UI：\n" + strUI);
strUI;

