/**基础参数定义*/
//是否输出日志
const isLog = 511;
//日志输出模块（2进制开关）
const modualSwitches = {
	"基础" : 1,
	"搜索" : 2,
	"发现" : 4,
	"详情" : 8,
	"目录" : 16,
	"正文" : 32,
	"基础性日志" : 64,
	"调试" : 128,
	"关键信息" : 256
}
//设置开关状态
const logModual = 0
// | modualSwitches.基础
// | modualSwitches.搜索
// | modualSwitches.发现
// | modualSwitches.详情
// | modualSwitches.目录
// | modualSwitches.正文
// | modualSwitches.基础性日志
	| modualSwitches.调试
	| modualSwitches.关键信息
	| 0;
//是否的切换展示
const selectedStatus = ["⬜","☑️"];
//展开折叠的切换展示
const colspasedStatus = ["📂","📁"];
//连接速度级别标志定义
const speedMark = ["🟩","🟦","🟨","🟧","🟫","🟪","🟥"];
//测速分级标准
const speedGrading = 400;
// [未测试，超级慢，联不通]
const disconnectedMark = ["❓","⬛","⛔"];
/**功能设置初始化*/
//符合条件的网址过滤规则
const checkPairs = {
	"/55/55353/" : "性奴隶之谍影传奇外传军妓的故事（全）同人改编"
}
//获取网址的发布页列表
const fetchHostsUrls = [ "http://diyibanzhu.net"];
//域名选择默认值
const defaultHosts = {
	"bz888888888.com" : {
		"url" : "https://www.bz888888888.com/",
		"token" : "",
		"lastTest" : -1,
		"delay" : -1,
		"err" : ""
	}
};
//小说状态
const states = {
	"🎒 全部状态" : 0,
	"✍️ 连载中" : 1,
	"📗 已完结" : 2
};
//小说排序
const orders = {
	"📬️ 最后更新" : "lastupdate",
	"💥 总人气" : "allvisit",
	"🈷️ 月人气"  : "monthvisit",
	"🔢 总字数" : "size",
	"🆕 最新上架" : "postdate"
};
//小说分类
const categories = {
	"📚️全部分类📚️" : 0,
	"🏰玄幻奇幻🔮" : 1,
	"🐉仙侠武侠🐦‍🔥" : 2,
	"🏙️都市言情👩‍❤‍👨" : 3,
	"🌠穿越历史⏳" : 4,
	"🤖科幻灵异👻" : 5,
	"🏫 藏 经 阁 🧙‍♂️" : 6,
	"🍀其他类别❇️" : 7
};
//按作者查询默认值
const defaultAuthors = ["俗人", "棺材里的笑声"];
/**登录及发现界面相关方法*/
//界面内容
var UI = [];
//内容展示模块（disc=发现界面；其他=登录界面）
var MD = "login";
//初始化发现界面参数
const optionsJson = {
	state : [],
	cate : [],
	order : [],
	author : defaultAuthors,
	hosts : [],
	mode : []
};
//初始化小说状态
for (let key in states) {
	optionsJson.state.push(key);
}
//小说排序数组
for (let key in orders) {
	optionsJson.order.push(key);
}
//初始化小说分类
for (let key in categories) {
	optionsJson.cate.push(key);
}
//初始化域名列表
for (let key in defaultHosts) {
	optionsJson.hosts.push(key + " " + disconnectedMark[0]);
	optionsJson.hosts.sort();
}
//生成发现界面链接
const initDiscoverUrl = (java,source,cate,offset) => {
	let args = getArgs(java,source);
	return `{{getHostUrl(java,source)}}shuku/${categories[cate]}-${orders[args.order]}-${states[args.state]}-{{page+${offset>0?offset-1:0}}}.html`;
}
//生成发现界面链接(自定义)
const initDiscoverUrlUD = (status,order,cate,offset) => {
	return `{{getHostUrl(java,source)}}shuku/${categories[cate]}-${orders[order]}-${states[status]}-{{page+${offset>0?offset-1:0}}}.html`;
}
//生成发现界面作者链接
const initDiscoverUrl_A = (author) => {
	return `{{getHostUrl(java,source)}}author.php?author=${author}`;
}
//生成发现界面搜索链接
const initDiscoverUrl_S = (keyWord) => {
	return `{{getHostUrl(java,source)}}s.php,{\\"charset\\":\\"GBK\\",\\"method\\":\\"POST\\",\\"body\\":\\"s=${keyWord}&page={{page }}\\"}`;
}
//切换发现模式
const changeDiscoverMode = (java,source,mode) => {
	let args = getArgs(java,source);
	args.discoverMode = mode;
	saveArgs(source, args);
	java.refreshExplore();
	source.refreshExplore();
}
//切换工作模式mode:[discover,setting,hosts]
const changeWorkMode = (java, source, mode) => {
	let args = getArgs(java, source);
	args.viewMode = mode;
	saveArgs(source, args);
	java.refreshExplore();
	source.refreshExplore();
}
//确认参数配置
const conmmitSetting = (java, source, infoMap) => {
	let args = getArgs(java, source);
	//传统发现
	if(args.discoverMode == "discover"){
		args.state = infoMap["state"];
		args.order = infoMap["order"];
		args.keyWord = infoMap["keyWord"].trim();
		args.offset= /[1-9]\d*/.test(infoMap["offset"]) ? infoMap["offset"] : 1;
	}
	args.viewMode = "discover";
	saveArgs(source, args);
	java.refreshExplore();
	source.refreshExplore();
}
//切换域名
const switchHost = (java, source, infoMap) => {
	let args = getArgs(java, source);
	args.domain = infoMap["domain"];
	saveArgs(source, args);
	java.refreshExplore();
	source.refreshExplore();
	T(java,`\n\n域名已切换到\n【${args.hosts[args.domain.split(" ")[0]].url}】\n\n`);
}
//完全还原
const formatD = (java, source) => {
	saveArgs(source,initArgs());
	java.refreshExplore();
	source.refreshExplore();
	T(java,"\n\n已完全还原成初始状态！！");
}
//添加自定义发现
function addUDDiscover(java, source, infoMap, type){
	let args = getArgs(java,source);
	let titleMark = "👓️";
	let titleStr = String(infoMap["自定义标题"]).trim();
	let url = "";
	if(!titleStr || titleStr.length == 0){
		T(java, "请输入标题！！\n\n\n\n");
		return;
	}
	if(type == "discover") {
		let status = String(infoMap["state"]);
		let order = String(infoMap["order"]);
		let cate = String(infoMap["cate"]);
		let offset = String(infoMap["起始页数"]);
		url = initDiscoverUrlUD(status, order, cate, offset);
		args.UDDiscover[titleMark + titleStr] = url;
		infoMap["起始页数"] = "";
		L(java,4,`添加自定义发现链接\n【${titleMark}${titleStr}】\n\n${url}\n\n`);
	} else if(type == "search") {
		titleMark = "🔎";
		let keyWord = String(infoMap["搜索关键字"]).trim();
		if(!titleStr || titleStr.length == 0){
			T(java, "请输入搜索关键字！！\n\n\n\n");
			return;
		}
		url = initDiscoverUrl_S(keyWord);
		args.UDDiscover[titleMark + titleStr] = url;
		infoMap["搜索关键字"] = "";
		L(java,4,`添加自定义搜索链接\n【${titleMark}${titleStr}】\n\n${url}\n\n`);
	}  else if(type == "author") {
		titleMark = "🧑‍💻";
		let author = String(infoMap["关注作者"]).trim();
		if(!titleStr || titleStr.length == 0){
			T(java, "请输入关注作者！！\n\n\n\n");
			return;
		}
		url = initDiscoverUrl_A(author);
		args.UDDiscover[titleMark + titleStr] = url;
		infoMap["关注作者"] = "";
		L(java,4,`添加自定义关注作者链接\n【${titleMark}${titleStr}】\n\n${url}\n\n`);
	} else {
		L(java,256,"自定义添加功能非法操作，不做处理！！");
		return;
	}
	args.UDDiscoverArr = [];
	for(var key in args.UDDiscover){
		args.UDDiscoverArr.push(key);
	}
	args.UDDiscoverArr.sort();
	infoMap["自定义标题"] = "";
	infoMap.save();
	saveArgs(source, args);
	T(java, "添加成功！！\n\n");
	java.refreshExplore();
	source.refreshExplore();
}
//删除自定义发现
function delUDDiscover(java, source, infoMap){
	let args = getArgs(java,source);
	let UDDStr = String(infoMap["UDDiscovers"]);
	L(java,4,"删除自定义发现【" + UDDStr + "】");
	args.UDDiscoverArr.splice(args.UDDiscoverArr.indexOf(UDDStr), 1);
	delete args.UDDiscover[UDDStr];
	infoMap["UDDiscovers"] = args.UDDiscoverArr[0];
