//源变量基础参数名
const argsKeys = ["domain", "keyWord", "order", "state", "offset", "viewMode", "discoverMode", "authors", "UDDiscoverArr", "hostArr", "UDDiscover", "hosts"];
//初始化源变量
const initArgs = () => {
	return  {
		"domain": optionsJson.hosts[0],
		"order": optionsJson.order[0],
		"state": optionsJson.state[0],
		"offset": 1,
		"viewMode": "discover",
		"discoverMode": "discover",
		"authors": defaultAuthors,
		"UDDiscover": {},
		"UDDiscoverArr": [],
		"keyWord": "",
		"hostArr": optionsJson.hosts,
		"hosts": defaultHosts
	};
}
//获取源变量参数
const getArgs = (java, source) => {
	let argsStr = source.getVariable();
	let args;
	if(!argsStr || argsStr == ""){
		TE(java,"重新初始化参数！")
		args = initArgs();
		saveArgs(source, args);
	} else {
		args = JSON.parse(argsStr);
		for (let k in argsKeys) {
			let tmpValue = args[argsKeys[k]];
			if(typeof(tmpValue) == "undefined"){
				TE(java,`参数${argsKeys[k]}不存在，重新初始化！`)
				let newArgs = initArgs();
				for(let key in args){
					if(args[key]){
						newArgs[key] = args[key];
					}
				}
				args = newArgs;
				saveArgs(source,args);
				break;
			}
		}
	}
	return args;
}
//保存参数
const saveArgs = (source, args) => {
	source.setVariable(JSON.stringify(args,null,"\t"));
}
//获取切换的域名
const getHostUrl = (java,source) => {
	let args = getArgs(java,source);
	return args.hosts[args.domain.split(" ")[0]].url;
}
/**登录、发现界面通用方法*/
//清理界面缓存
const clearUI = () => {
	UI = [];
}
//向界面中添加元素
const pushUI = (obj) => {
	UI .push(obj);
}
//创建菜单元素
const creatEle = (info) => {
	let nameN = info.modual == "disc" ? "title" : "name";
	let nameStr = info.name;;
	let eleStr = "";
	let pct = 1;
	let grow = 1;
	if(parseInt(info.cols/10) > 1){
		grow = 999;
	}
	let charsStr = JSON.stringify(info.chars);
	let defaultStr = JSON.stringify(info.default);
	switch (info.cols%10){
		case 2:
			pct = 0.46;
			break;
		case 3:
			pct = 0.29;
			break;
		case 4:
			pct = 0.2;
			break;
		case 5:
			pct = 0.14;
			break;
		case 9:
			pct = 0.6;
			break;
	}
	switch(info.type){
		case "title":
			eleStr = `{"${nameN}":"${nameStr}","type":"button","style":{"layout_flexGrow":${grow},"layout_flexBasisPercent":1.2,"layout_wrapBefore":true}}`;
			break;
		case "url":
			eleStr = `{"${nameN}":"${nameStr}","url":"${info.url}","style":{"layout_flexGrow":${grow},"layout_flexBasisPercent":${pct}}}`;
			break;
		case "button":
			eleStr = `{"${nameN}":"${nameStr}","type":"button","action":"${info.func}","style":{"layout_flexGrow":${grow},"layout_flexBasisPercent":${pct}}}`;
			break;
		case "buttonW":
			eleStr = `{"${nameN}":"${nameStr}","type":"button","action":"${info.func}","style":{"layout_flexGrow":${grow},"layout_flexBasisPercent":${pct},"layout_wrapBefore":true}}`;
			break;
		case "text":
			eleStr = `{"${nameN}":"${nameStr}","type":"text","style":{"layout_flexGrow":${grow},"layout_flexBasisPercent":${pct}}}`;
			break;
		case "password":
			eleStr = `{"${nameN}":"${nameStr}","type":"password","style":{"layout_flexGrow":${grow},"layout_flexBasisPercent":${pct}}}`;
			break;
		case "toggle":
			eleStr = `{"${nameN}":"${nameStr}","type":"toggle","viewName":"\\"${info.viewName}\\"","action":"${info.func}","chars":${charsStr},"default":${defaultStr},"style":{"layout_flexGrow":${grow},"layout_flexBasisPercent":${pct}}}`;
			break;
		case "select":
			eleStr = `{"${nameN}":"${nameStr}","type":"select","viewName":"\\"${info.viewName}\\"","action":"${info.func}","chars":${charsStr},"default":${defaultStr},"style":{"layout_flexGrow":${grow},"layout_flexBasisPercent":${pct}}}`;
	}
	return JSON.parse(eleStr);
}
//创建标题（只有文字没有作用的按钮）
const newTitle = (name,modual) => {
	var di = {};
	di.modual = modual;
	di.type = "title";
	di.name = name;
	return creatEle(di);
}
//创建链接（仅限发现界面）
const newUrl = (name,url,cols) => {
	var di = {};
	di.modual = "disc";
	di.type = "url";
	di.name= name;
	di.url= url;
	di.cols= cols;
	return creatEle(di);
}
//创建按钮（执行func）
const newButton = (name,modual,func,cols) => {
	var di = {};
	di.modual = modual;
	di.type = "button";
	di.name = name;
	di.func= func;
	di.cols = cols;
	return creatEle(di);
}
//创建强制换行按钮（执行func）
const newButtonW = (name,modual,func,cols) => {
	var di = {};
	di.modual = modual;
	di.type = "buttonW";
	di.name = name;
	di.func= func;
	di.cols = cols;
	return creatEle(di);
}
//创建文本输入（⚠️输入完毕执行func没有测试过）
const newText = (name,modual,func,cols) => {
	var di = {};
	di.modual = modual;
	di.type = "text";
	di.name = name;
	di.func= func;
	di.cols= cols;
	return creatEle(di);
}
//创建密码输入（仅限登录界面）
const newPwd = (name,cols) => {
	var di = {};
	di.modual = "login";
	di.type = "password";
	di.name = name;
	di.cols= cols;
	return creatEle(di);
}
//创建下拉列表选择框（选中后执行func）
const newSelect = (name,viewName,modual,chars,func,cols) => {
	var di = {};
	di.modual = modual;
	di.type = "select";
	di.name = name;
	di.viewName= viewName;
	di.func= func;
	di.cols = cols;
	di.chars = chars;
	di.default = chars[0];
	return creatEle(di);
}
//创建切换按钮（选中后执行func）
const newToggle = (name,viewName,modual,chars,func,cols) => {
	var di = {};
	di.modual = modual;
	di.type = "toggle";
	di.name = name;
	di.viewName= viewName;
	di.func= func;
	di.cols = cols;
	di.chars = chars;
	di.default = chars[0];
	return creatEle(di);
}

