        TC_to_SC = true;
    }
    if ($$$.TC_to_SC == true) {
        login('【简繁转换提示】' + n(2) + '已关闭繁体转换，请刷新书籍');
        $$$.TC_to_SC = false;
        put($$$);
    } else {
        login('【简繁转换提示】' + n(2) + '已开启繁体转换，请刷新书籍');
        $$$.TC_to_SC = true;
        put($$$);
    }
}
function settle() {
    if (settle == undefined) {
        settle = true;
    }
    if ($$$.settle == true) {
        login('【目录整理提示】' + n(2) + '已关闭目录整理，请刷新目录');
        $$$.settle = false;
        put($$$);
    } else {
        login('【目录整理提示】' + n(2) + '已开启目录整理，请刷新目录');
        $$$.settle = true;
        put($$$);
    }
}

